public class EventFilterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<Event> events = new java.util.ArrayList<>();
        events.add(new Event("click", 12));
        events.add(new Event("key", 40));
        events.add(new Event("click", 3));
        events.add(new Event("scroll", 7));

        check("keep clicks only",
                "[Event[kind=click, size=12], Event[kind=click, size=3]]",
                String.valueOf(EventFilter.keep(events, e -> e.kind().equals("click"))));

        check("keep size >= 10",
                "[Event[kind=click, size=12], Event[kind=key, size=40]]",
                String.valueOf(EventFilter.keep(events, e -> e.size() >= 10)));

        check("predicate combining both fields",
                "[Event[kind=scroll, size=7]]",
                String.valueOf(EventFilter.keep(events, e -> e.kind().equals("scroll") && e.size() < 10)));

        check("keep everything", 4, EventFilter.keep(events, e -> true).size());

        check("keep nothing", "[]", String.valueOf(EventFilter.keep(events, e -> false)));

        check("input list is untouched", 4, events.size());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

