record Event(String kind, int size) {}

public class EventFilter {

    public static java.util.List<Event> keep(
            java.util.List<Event> events, java.util.function.Predicate<Event> p) {
        java.util.List<Event> kept = new java.util.ArrayList<>();
        for (Event e : events) {
            if (p.test(e)) {
                kept.add(e);
            }
        }
        return kept;
    }
}
